style.css:
/* ? Fondo personalizado Roblox (para Stylish) */
/* Imagen: https://i.imgur.com/nXMZwe4.jpeg */

@namespace url(http://www.w3.org/1999/xhtml);
@-moz-document domain("roblox.com"), domain("www.roblox.com") {
html, body {
    background: #000 url("https://i.imgur.com/nXMZwe4.jpeg") no-repeat center center fixed !important;
    background-size: cover !important;
    color: #fff !important;
  }

  /* Hacer transparentes los contenedores principales */
  #app, #root, .container-main, .content, .theme-base, .container-lg, .container-fluid {
    background: transparent !important;
  }

  /* Navbar y footer semitransparentes */
  header, nav, footer, .navbar, #header, #navigation, .footer-container {
    background: rgba(0, 0, 0, 0.35) !important;
    backdrop-filter: blur(4px) !important;
  }

  /* Paneles y tarjetas */
  .card, .modal-content, .panel, .profile-card, .rbx-body, .container-section {
    background: rgba(0, 0, 0, 0.55) !important;
    color: #f5f5f5 !important;
    backdrop-filter: blur(3px) !important;
  }

  /* Texto y enlaces */
  * {
    color: #f3f3f3 !important;
  }

  a {
    color: #ff4c4c !important;
  }

  img {
    image-rendering: auto !important;
  }
}
